from textstats import word_freq

def test_word_freq_basic():
    # Ordinary, legitimate use case: counting a single word
    result = word_freq("hello")
    assert result == {"hello": 1}

    # Another ordinary use case: counting multiple distinct words
    result = word_freq("hello world")
    assert result == {"hello": 1, "world": 1}

if __name__ == "__main__":
    test_word_freq_basic()

